-- RH (01/10/2026) — Funções operacionais de obra, bloco 1 de 3: Chefe de Equipa, Pedreiro, Servente, Canalizador, Eletricista.
-- Para o Grupo Obrajusta / Tudo Casa (as funções são do grupo; o local de trabalho indica a Obrajusta II).
-- Correr DEPOIS de rh-2-3-perfis.sql (liga cada função ao seu perfil de avaliação). Só insere; se já existir, não mexe.
INSERT INTO public.rh_funcoes (grupo_id, codigo, nome, departamento, nivel, cor, missao, reporta_a, local_trabalho, horario,
  ferramentas, ordem, requisitos, responsabilidades, nao_e_do_cargo, competencias, indicadores, perfil_avaliacao_id)
SELECT g.id, v.codigo, v.nome, 'Obra', v.nivel, v.cor, v.missao, v.reporta, 'Obras da Obrajusta II (Mirandela e região) e estaleiro', 'Conforme horário da obra',
  v.ferramentas, v.ordem, v.requisitos, v.responsabilidades, v.nao, v.competencias, v.indicadores,
  (SELECT p.id FROM public.rh_aval_perfis p WHERE p.grupo_id = g.id AND p.codigo = v.perfil)
FROM public.empresa_grupos g
CROSS JOIN (VALUES
('chefe_equipa', 'Chefe de Equipa', 'operacional', '#b45309', 'chefia', 'Pôr a equipa a produzir bem e em segurança todos os dias, garantindo que o que foi planeado pelo Diretor de Obra acontece no terreno.', 'Diretor de Obra / Engenheiro Civil', 'Ferramentas da especialidade, plano de trabalhos, Clariza (cartões de obra)', 50,
 '{"obrigatorios":["Experiência mínima de 5 anos em obra, com pelo menos 2 a coordenar pessoas","Leitura de desenhos e medições","Carta de condução categoria B"],"valorizados":["Formação em segurança na construção","Conhecimento de várias especialidades (alvenaria, acabamentos, redes)"]}'::jsonb,
 '[{"area":"Equipa","itens":["Distribuir as tarefas do dia e confirmar que cada pessoa tem material e ferramentas","Acompanhar o trabalho e corrigir na hora o que não está bem feito","Integrar quem entra na equipa"]},{"area":"Obra","itens":["Registar diariamente o avanço, as faltas de material e os imprevistos","Garantir o cumprimento das regras de segurança e do uso de EPI","Deixar a obra arrumada e fechada no fim do dia"]}]'::jsonb,
 '["Alterar o projeto ou o método sem validação do Diretor de Obra","Encomendar material fora do circuito de Compras"]'::jsonb, '{"profissionais":["Domínio técnico das especialidades que coordena","Planeamento do dia e da semana"],"comportamentais":["Liderança pelo exemplo","Comunicação clara e firme"]}'::jsonb, '["Tarefas da semana concluídas no prazo","Trabalhos refeitos por defeito de execução","Ocorrências de segurança","Registos diários entregues"]'::jsonb),
('pedreiro', 'Pedreiro', 'operacional', '#a16207', 'operacional', 'Executar alvenarias, rebocos, betonilhas e trabalhos de construção com rigor de esquadria, prumo e nível.', 'Chefe de Equipa', 'Colher, talocha, nível, fio de prumo, régua, betoneira, rebarbadora', 51,
 '{"obrigatorios":["Experiência comprovada em alvenarias e rebocos","Leitura de cotas e medidas"],"valorizados":["Experiência em reabilitação de edifícios antigos","Formação profissional em construção civil"]}'::jsonb,
 '[{"area":"Execução","itens":["Levantar paredes de tijolo e bloco a prumo e nível","Executar rebocos, betonilhas e regularizações","Assentar pré-fabricados e executar pequenos trabalhos de betão"]},{"area":"Obra","itens":["Preparar argamassas na dosagem indicada","Proteger o trabalho feito e limpar o posto no fim do dia"]}]'::jsonb,
 '["Remover elementos estruturais sem ordem do Diretor de Obra"]'::jsonb, '{"profissionais":["Rigor de esquadria, prumo e nível","Conhecimento de materiais e argamassas"],"comportamentais":["Brio no acabamento","Trabalho em equipa"]}'::jsonb, '["Retrabalho por defeito de execução","Metros executados face ao planeado","Ocorrências de segurança"]'::jsonb),
('servente', 'Servente', 'operacional', '#78716c', 'operacional', 'Apoiar as equipas de obra para que nunca falte material, acesso ou limpeza no posto de trabalho.', 'Chefe de Equipa', 'Carrinho de mão, pá, picareta, martelo pneumático, ferramentas manuais', 52,
 '{"obrigatorios":["Disponibilidade para trabalho físico em obra","Cumprimento das regras de segurança"],"valorizados":["Carta de condução categoria B","Experiência anterior em obra"]}'::jsonb,
 '[{"area":"Apoio","itens":["Transportar e distribuir materiais pelos postos de trabalho","Preparar argamassas sob indicação do oficial","Executar demolições e abertura de roços quando indicado"]},{"area":"Arrumação","itens":["Manter o estaleiro e a obra limpos e arrumados","Recolher e separar resíduos de construção"]}]'::jsonb,
 '["Operar máquinas sem formação e autorização"]'::jsonb, '{"profissionais":["Conhecimento básico de materiais e ferramentas"],"comportamentais":["Prestabilidade","Vontade de aprender"]}'::jsonb, '["Faltas e atrasos","Ocorrências de segurança","Avaliação do chefe de equipa sobre o apoio prestado"]'::jsonb),
('canalizador', 'Canalizador', 'operacional', '#0369a1', 'operacional', 'Executar e reparar redes de águas, esgotos e gás e instalar louças e equipamentos sanitários sem fugas nem retrabalho.', 'Chefe de Equipa', 'Máquina de termofusão, prensadora (multicamada), corta-tubos, maçarico, bomba de ensaio', 53,
 '{"obrigatorios":["Experiência em redes de água (multicamada, PPR, cobre) e esgotos (PVC)","Execução de ensaios de estanquidade"],"valorizados":["Habilitação para redes de gás","Instalação de sistemas solares térmicos, bombas de calor ou termoacumuladores"]}'::jsonb,
 '[{"area":"Redes","itens":["Abrir roços e executar redes de abastecimento e drenagem conforme projeto","Ensaiar as redes antes de fechar paredes e pavimentos"]},{"area":"Equipamentos","itens":["Instalar louças, bases de duche, torneiras e esquentadores","Diagnosticar e reparar fugas e entupimentos"]}]'::jsonb,
 '["Fechar paredes sem ensaio registado"]'::jsonb, '{"profissionais":["Leitura de projetos de redes","Conhecimento de materiais e diâmetros"],"comportamentais":["Atenção ao pormenor","Cuidado no atendimento ao cliente em casa ocupada"]}'::jsonb, '["Fugas ou reclamações após entrega","Ensaios registados","Retrabalho"]'::jsonb),
('eletricista', 'Eletricista', 'operacional', '#ca8a04', 'operacional', 'Executar instalações elétricas e de telecomunicações seguras e conformes, de modo a passarem à primeira na inspeção.', 'Chefe de Equipa', 'Multímetro, testador de isolamento e diferenciais, ferramentas isoladas, berbequim', 54,
 '{"obrigatorios":["Experiência em instalações elétricas de baixa tensão","Leitura de esquemas e quadros elétricos","Cumprimento das regras de segurança em trabalhos elétricos"],"valorizados":["Formação certificada de eletricista","Experiência em ITED (telecomunicações), domótica ou fotovoltaico"]}'::jsonb,
 '[{"area":"Instalação","itens":["Executar tubagens, cablagem e aparelhagem conforme projeto","Montar e ligar quadros elétricos","Medir e registar isolamentos, terras e diferenciais"]},{"area":"Assistência","itens":["Diagnosticar e reparar avarias","Deixar a instalação identificada e o quadro legendado"]}]'::jsonb,
 '["Trabalhar em tensão sem autorização e meios adequados"]'::jsonb, '{"profissionais":["Conhecimento das regras técnicas de instalações elétricas","Diagnóstico de avarias"],"comportamentais":["Rigor","Responsabilidade com a segurança"]}'::jsonb, '["Inspeções aprovadas à primeira","Avarias reportadas após entrega","Retrabalho"]'::jsonb)
) AS v(codigo, nome, nivel, cor, perfil, missao, reporta, ferramentas, ordem, requisitos, responsabilidades, nao, competencias, indicadores)
WHERE g.nome = 'Grupo Obrajusta / Tudo Casa'
ON CONFLICT (grupo_id, codigo) DO NOTHING;

SELECT f.nome, f.nivel, p.nome AS perfil_de_avaliacao
FROM public.rh_funcoes f LEFT JOIN public.rh_aval_perfis p ON p.id = f.perfil_avaliacao_id
WHERE f.departamento = 'Obra' ORDER BY f.ordem;
